/**
 * The only link to the code generated by the Power Apps CLI (setup.ps1).
 *
 * The CLI names the files after the table display names and the flow names, so the
 * services are looked up by file name, case-insensitively, instead of being imported
 * by a fixed name. If a service is missing the app shows which one to generate.
 */
import type { IOperationResult } from "@microsoft/power-apps/data";
import { text } from "../i18n";

export interface QueryOptions {
  select?: string[];
  filter?: string;
  orderBy?: string[];
  top?: number;
  maxPageSize?: number;
  skipToken?: string;
}

export interface TableService {
  getAll(options?: QueryOptions): Promise<IOperationResult<unknown[]>>;
  get(id: string, options?: { select?: string[] }): Promise<IOperationResult<unknown>>;
  create(record: Record<string, unknown>): Promise<IOperationResult<unknown>>;
  update(id: string, changedFields: Record<string, unknown>): Promise<IOperationResult<unknown>>;
  delete(id: string): Promise<IOperationResult<void>>;
  downloadImage?(id: string, columnName: string, fullSize?: boolean): Promise<IOperationResult<Uint8Array>>;
}

export interface FlowService {
  Run(input: Record<string, unknown>): Promise<IOperationResult<unknown>>;
}

const modules = import.meta.glob(["../generated/services/*.ts", "../services/*.ts"], {
  eager: true,
}) as Record<string, Record<string, unknown>>;

export class MissingServiceError extends Error {
  constructor(label: string, candidates: string[]) {
    super(text().repository.missingService(label, candidates.map((c) => `${c}Service.ts`).join(" / ")));
    this.name = "MissingServiceError";
  }
}

function resolve<T>(label: string, candidates: string[]): T {
  const wanted = new Set(candidates.map((c) => `${c}service.ts`.toLowerCase()));
  for (const [path, exports] of Object.entries(modules)) {
    const file = path.split("/").pop()?.toLowerCase() ?? "";
    if (!wanted.has(file)) continue;
    const service = Object.values(exports).find((value) => typeof value === "function");
    if (service) return service as T;
  }
  throw new MissingServiceError(label, candidates);
}

const cache = new Map<string, unknown>();

function lazy<T>(label: string, candidates: string[]): () => T {
  return () => {
    if (!cache.has(label)) cache.set(label, resolve<T>(label, candidates));
    return cache.get(label) as T;
  };
}

// Table services: name from the display collection name (current CLI) or the entity set name.
export const communications = lazy<TableService>("Adopta Communications", [
  "Adoptacommunications",
  "Vm_adoptacommunications",
]);
export const communicationGroups = lazy<TableService>("Adopta Communication Groups", [
  "Adoptacommunicationgroups",
  "Vm_adoptacommunicationgroups",
]);
export const audienceGroups = lazy<TableService>("Adopta Audience Groups", [
  "Adoptaaudiencegroups",
  "Vm_adoptaaudiencegroups",
]);
export const deliveries = lazy<TableService>("Adopta Deliverys", [
  "Adoptadeliverys",
  "Adoptadeliveries",
  "Vm_adoptadeliveries",
]);
export const settings = lazy<TableService>("Adopta Settings", ["Adoptasettings", "Vm_adoptasettings"]);

// Flow services: name from the flow display name.
export const scheduleFlow = lazy<FlowService>("AdoptaScheduleCommunication", ["AdoptaScheduleCommunication"]);
export const manageFlow = lazy<FlowService>("AdoptaManageCommunication", ["AdoptaManageCommunication"]);

/** Inputs of the "When Power Apps calls a flow (V2)" triggers: CommunicationId = text, Operation = text_1. */
export function scheduleInput(communicationId: string): Record<string, unknown> {
  return { text: communicationId };
}

export function manageInput(communicationId: string, operation: string): Record<string, unknown> {
  return { text: communicationId, text_1: operation };
}
